create or replace TABLE LDL_PRODUCTION_CLONE_GOOGLE_20260608_1030.P_LEW_CORE.T_MDM_ITEM_HIST_2 (
	CLIENT_ID NUMBER(38,0) NOT NULL COMMENT 'Technical column required by the used ETL framework. Static 7 for all rows.',
	MDM_ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'surrogate key NFPO item_2 instance\n            CBX: CNT_ITEM.REF_NO',
	CBX_ITEM_VERSION_NR NUMBER(38,0) NOT NULL COMMENT 'technical version of the NFPO item_2 in the source system\n            CBX: CNT_ITEM.VERSION',
	CBX_ITEM_DOC_STATUS VARCHAR(100) COLLATE 'en-ci' COMMENT 'technical status_2 of the NFPO item_2 in the source system (active,inactive,cancelled)\n            CBX: CNT_ITEM.DOC_STATUS',
	CBX_ITEM_CHANGE_TMSP TIMESTAMP_NTZ(9) NOT NULL COMMENT 'change timestamp of NFPO item_2 instance record in the source system\n            CBX: CNT_ITEM.UPDATED_ON',
	MARKET_SID NUMBER(38,0) COMMENT 'foreign key NFPO market\n            CBX: CNT_ITEM.LDL_CONTINENT_TYPE',
	ITEM_FAM_GRP_SID NUMBER(38,0) COMMENT 'foreign key item_2 family group\n            CBX: CNT_ITEM.LDL_ARTICLE_GROUP',
	BRAND_SID NUMBER(38,0) COMMENT 'foreign key brand_2\n            CBX: CNT_ITEM.LDL_BRAND',
	COUNTRY_POL_SID_ORIGIN NUMBER(38,0) COMMENT 'foreign key political country_2, here the manufacturing country_2 of the item_2 is used\n            CBX: CNT_ITEM.LDL_COUNTRY_OF_ORIGIN',
	MDM_SUP_SID NUMBER(38,0) COMMENT 'foreign key NFPO supplier_2\n            CBX: CNT_ITEM.LDL_DEFAULT_VENDOR_REF',
	EAN_OWNERSHIP_CD VARCHAR(100) COMMENT 'NFPO GTIN assignement responisbility code\n            CBX: CTM_VENDOR.CUST_CODELIST1',
	SUP_FINAL_FG NUMBER(38,0) COMMENT 'indicated whether the supplier_2 is finally fixed\n            CBX: CNT_ITEM.LDL_FINAL_VENDOR',
	ITEM_WORKFLOW_STATUS_ID NUMBER(38,0) COMMENT 'foreign key NFPO item_2 workflow status_2\n            CBX: CNT_ITEM.STATUS_2 substringAfter(\""customStatus\"")',
	ITEM_CLASS_CD VARCHAR(20) COLLATE 'en-ci' COMMENT 'NFPO item_2 classification code related to item_2 creation and usage over time\n            CBX: CNT_ITEM.LDL_ARTICLE_TYPE',
	BUY_STATUS_CD VARCHAR(20) COLLATE 'en-ci' COMMENT 'NFPO status_2 code related to the order quantity definition process for the local NFPOs of items\n            CBX: CNT_ITEM.LDL_COUNTRY_ORDER_STATUS',
	DISPLAY_TYPE_CD VARCHAR(20) COLLATE 'en-ci' COMMENT 'NFPO display type code\n            CBX: CNT_ITEM.LDL_DISPLAY_TYPE',
	HIER_NODE_SID NUMBER(38,0) COMMENT 'FK Node\n            CBX: CNT_ITEM.HIERARCHY_HCL, HIERARCHY_FULL_CODE',
	ITEM_COLLECTION VARCHAR(300) COMMENT 'Item_2 collection (related group of articles, free text)\n            CBX: CNT_ITEM.LDL_ITEM_COLLECTION',
	ITEM_NOTES VARCHAR(4000) COMMENT 'Item_2 procurement notes;\n            CBX: CNT_ITEM.LDL_EK_NOTE',
	GUARANTEE_CD VARCHAR(100) COMMENT 'NFPO warranty duration code\n            CBX: CNT_ITEM.LDL_GUARANTEE',
	GUARANTEE_TYPE_CD VARCHAR(100) COMMENT 'NFPO warranty type code\n            CBX: CNT_ITEM.LDL_WARRANTY_ART_TYPE',
	GUARANTEE_ART VARCHAR(4000) COLLATE 'en-ci' COMMENT 'NFPO warranty type long description\n            CBX: CNT_ITEM.LDL_ART',
	ITEM_QUALITY_CLASS_CD VARCHAR(20) COLLATE 'en-ci' COMMENT 'NFPO code for item_2 quality classification\n            CBX: CNT_ITEM.LDL_ARTICLE_CLASS',
	MDM_PILLAR_SID NUMBER(38,0) COMMENT 'surrogate key, identifier of the pillar in NFPO source system, alternative item_2 grouping for non food items in addition to the standard grouping based on item_2 families\n            CBX: CNT_ITEM.LDL_PILLAR',
	MAIN_PILLAR_CD VARCHAR(100) COMMENT 'main pillar code  (TX/HG) \n            CBX: CNT_ITEM.PRODUCT_CATEGORY_VALUE',
	KFL_BRAND_SID NUMBER(38,0) COMMENT 'surrogate key, identifies the brand_2 in case of selling in a Kaufland country_2\n            CBX: CNT_ITEM.LDL_BRAND_KL',
	MDM_ITEM_SPLIT_ROLE_CD VARCHAR(100) COMMENT 'NFPO code for the roles items can have in the split process to create Kaufland specific items from standard NFPO items due to different item_2 granularity requirements in Kaufland compared to Lidl (\""Vereinzelung\"")\n            CBX: CNT_ITEM.LDL_PARENT_OR_CHILD',
	MDM_LIST_TYPE_CD VARCHAR(100) COMMENT 'NFPO codes for list types of items\n            CBX: CNT_ITEM.LDL_ASSORT_TYPE',
	MDM_ITEM_SPLIT_METHOD_CD VARCHAR(100) COMMENT 'NFPO code for the split methods in the split process to create Kaufland specific items from standard NFPO items due to different item_2 granularity requirements in Kaufland compared to Lidl (\""Vereinzelung\"")\n            CBX: CNT_ITEM.LDL_STYLE_SPLIT',
	INNOVATION_FG NUMBER(38,0) COMMENT 'indicates whether an item_2 is an innovation article (1) or not (0) \n            CBX: CNT_ITEM.LDL_INNOVATION_ART',
	SEASON_NAME VARCHAR(100) COMMENT 'name of the season in case of a season relaterd item_2\n            CBX: CNT_ITEM.SEASON',
	CATALOG_FG NUMBER(38,0) COMMENT 'indicator whether an item_2 is a catalog item_2 or not, catalog items will get extra item_2 instances for every range selection where they are valid. The conditions and proterties remain unchanged.\n            CBX: CNT_ITEM.LDL_CAT_INDICATOR',
	CANCEL_REASON_NAME VARCHAR(100) COMMENT 'cancellation reason name if the item_2 has been cancelled\n            CBX: CNT_ITEM.LDL_CANCELLATION_REASON',
	INITIAL_RANGE_PLAN_CD VARCHAR(20) COMMENT 'initial charge ot the item_2\n            CBX: CNT_ITEM.LDL_INITIAL_LOT_NO',
	LDL_RELEVANT_FG NUMBER(38,0) COMMENT 'indicates whethter this item_2 is relevant to be sold by Lidl\n            CBX: CNT_ITEM.LDL_NO_LIDL_ITEM',
	KFL_RELEVANT_FG NUMBER(38,0) COMMENT 'indicates whethter this item_2 is relevant to be sold by Kaufland\n            CBX: CNT_ITEM.LDL_KL_DECISION',
	PACKAGE_TYPE_CD VARCHAR(100) COMMENT 'NFPO outer package_2 type codes for items\n            CBX: CNT_ITEM.LDL_PACKING_TYPE',
	CONTROLLED_PRICE_FG NUMBER(38,0) COMMENT 'indicates wheter the price is controlled outside NFPO\n            CBX: CNT_ITEM.LDL_BINDING_PRICE',
	ITEM_HIGHLIGHT_FG NUMBER(38,0) COMMENT 'Indicates whether the item_2 should be placed prominently during the internal trade show\n            CBX: CNT_ITEM.LDL_BRIEF_HIGHLIGHT',
	INITIAL_ORDER_FG NUMBER(38,0) COMMENT 'Indicator whether this item_2 instance initiates the first order for an catalog item_2\n            CBX: CNT_ITEM.LDL_INITIAL_ORDER',
	ITEM_UNIT_UOM_SID NUMBER(38,0) COMMENT 'indicator in the item_2 planning process: surrogate key item_2 content unit_2 of measurement. interpretation depends on the overall composition of the item_2 \n            CBX: CNT_ITEM.LDL_CONTAINER_UNIT',
	ITEM_UNIT_UOM_CD VARCHAR(100) COMMENT 'indicator in the item_2 planning process: code of the item_2 content unit_2 of measurement. interpretation depends on the overall composition of the item_2\n            CBX: CNT_ITEM.LDL_CONTAINER_UNIT',
	ITEM_UNIT_QTY NUMBER(38,5) COMMENT 'indicator in the item_2 planning process: quantity of the content of units of the item. interpretation depends on the overall composition of the item_2 \n            CBX: CNT_ITEM.LDL_CONTAINER_VOLUME',
	ITEM_UNIT_CNT NUMBER(38,0) COMMENT 'indicator in the item_2 planning process: number of units the item_2 consists of for the main variant. interpretation depends on the overall composition of the item_2 \n            CBX: CNT_ITEM.LDL_NUMBER_OF_CONTAINER',
	MINIMAL_ORDER_QTY NUMBER(38,5) COMMENT 'minimum of the order quantity for a catalog item_2\n            CBX: CNT_ITEM.LDL_MOQ',
	ITEM_INITIATING_INT_ORG_SID NUMBER(38,0) COMMENT 'organisation which initiates the item_2 due to competitor items\n            CBX: CNT_ITEM.LDL_STORE_CHECK_NAME',
	ITEM_PROPOSING_INT_ORG_SID NUMBER(38,0) COMMENT 'organisation which did propose this item_2\n            CBX: CNT_ITEM.LDL_COUNTRY_PROPOSAL',
	CASE_SIZE_QTY NUMBER(38,5) COMMENT 'predefined number of items in the sort boxes of the item. all sort boxes will have the same case_size_qty. \n            CBX: CNT_ITEM.LDL_UNIT_OF_CARTON',
	CONTRACT_EXPIRY_DT DATE COMMENT 'for catalog items here the expiry date of the contract is stored\n            CBX: CNT_ITEM.LDL_CONTRACT_EXPIRY_DATE',
	MDM_ITEM_COMPOSITION_CD VARCHAR(100) COMMENT 'indicator in the item_2 planning process: indicates whether an item_2 has relevant variants or consists of certain sub parts. interpretation depends on the overall composition of the item. assort  or assemble: (x)fach sortiert oder (x)teilig\n            CBX:CNT_ITEM.LDL_ASSORTMENT',
	ITEM_VARIANT_CNT NUMBER(38,0) COMMENT 'indicator in the item_2 planning process: number of relevant variants the item_2 the item_2 has from the design point of view. interpretation depends on the overall composition of the item_2 \n            CBX: CNT_ITEM.LDL_NUM_OF_UNITS',
	MDM_CASE_COMPOSITION_CD VARCHAR(100) COMMENT 'indicator in the item_2 planning process: indicates whether the case will be filled by items directly or by subcases which contain a predefined number of items. interpretation depends on the overall composition of the item_2 \n            CBX:CNT_ITEM.LDL_PACK_TYPE',
	QUALITY_COMMENT_TXT VARCHAR(1000) COMMENT 'free text remark related to the NFPO item_2 from the quality development team point of view\n            CBX: CNT_ITEM.LDL_REMARK_QE',
	PURCH_COMMENT_TXT VARCHAR(1000) COMMENT 'free text remark related to the NFPO item_2 from the purchasing team point of view\n            CBX: CNT_ITEM.LDL_REMARK_EK',
	DELETED_FG NUMBER(38,0) NOT NULL COMMENT 'Deleted_fg = 1 means that the record is not available in the source system or a delete information is set in the source system between dwh_valid_from and dwh_valid_to.',
	DWH_VALID_FROM DATE NOT NULL COMMENT 'Begin of the validity_2 interval of the record, oldest record of the history starts with 1900-01-01 (minus infinity).',
	DWH_VALID_TO DATE NOT NULL COMMENT 'End of the validity_2 interval of the record, newest record of the history ends with 9999-12-30 (plus infinity).',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'Identifier of the last run which inserted or updated the record. -1 means manually inserted.',
	DWH_CREATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Creation timestamp of the record in the DWH.',
	DWH_UPDATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Timestamp of the last update of the record in the DWH.',
	CBX_ITEM_CREATED_TMSP TIMESTAMP_NTZ(9) NOT NULL COMMENT 'creation timestamp of NFPO item_2 instance record in the source system\n            CBX: CNT_ITEM.CREATED_ON',
	MDM_CUST_NEED_TYPE_CD VARCHAR(100) COMMENT 'Code to classify the assortment by general customer needs.\n            CBX: CNT_ITEM.LDL_FOCUS_CATEGORY',
	ASSORT_PROFILE_TYPE_CD VARCHAR(100) COMMENT 'Code to indicate the importance profile of the item_2 in the assortment (Pflicht, Profilierung, Ergänzung).\n            CBX: CNT_ITEM.LDL_FMS_ASSORTMENT',
	MDM_CUST_NEED_SUBTYPE_CD VARCHAR(100) COMMENT 'Code to classify the assortment by detailed customer needs.\n            CBX: CNT_ITEM.LDL_CATEGORY_NEEDS',
	CORE_ASSORT_TYPE_CD VARCHAR(100) COMMENT 'Code  of the type how the item_2 can be regarded to be part of the Lidl core assortment.\n            CBX: CNT_ITEM.ldl_core_article',
	MDM_SMART_ITEM_FG NUMBER(38,0) COMMENT 'The flag indicates whether an item_2 is regarded to be a smart item_2 or not.\n            The definition of a smart item_2 is not standardized. It can be an IOT item_2 or have connectivity / networking capabilities. Items whose networking capability is a central component of their use, like a printer, may not be considered smart items.\n            CBX: CNT_ITEM.LDL_IOT',
	MDM_LOGISTICS_CLASS_CD VARCHAR(100) COMMENT 'Code to classify the way the items will be transported from the central warehouse of OWIM into the countries.\n            CBX: CNT_ITEM.LDL_DELIVERY_TYPE',
	MDM_LDL_SALES_PACKAGING_TYPE_CD VARCHAR(100) COMMENT 'Code of the sales_2 packaging type to be used for sales_2 in the line of business Lidl.\n            CBX: CNT_ITEM.LDL_RETAIL_PACKAGING',
	MDM_KFL_SALES_PACKAGING_TYPE_CD VARCHAR(100) COMMENT 'Code of the sales_2 packaging type to be used for sales_2 in the line of business Kaufland.\n            CBX: CNT_ITEM.LDL_RETAIL_PACKAGING_KL',
	EU_DATA_ACT_RELEVANT_FG NUMBER(38,0) COMMENT 'The flag indicates whether an item_2 is relevant for EU Data act or not.\n            CBX:CNT_ITEM.LDL_EU_DATA_ACT',
	constraint PK_T_MDM_ITEM_HIST primary key (MDM_ITEM_SID, DWH_VALID_FROM)
)COMMENT='Instances of NFPO items in the quarterly item_2 planning and ordering process. For catalog items there might be several instances in this table, all sharing the same international article number.\n             CBX: CNT_ITEM_2'
;
